package com.nivor.project.dto;import com.nivor.project.*;import java.time.*;public record ProjectResponse(Long id,Long workspaceId,String name,String description,ProjectStatus status,int progress,LocalDate deadline,LocalDateTime createdAt,LocalDateTime updatedAt){public static ProjectResponse from(Project p){return new ProjectResponse(p.getId(),p.getWorkspace()==null?null:p.getWorkspace().getId(),p.getName(),p.getDescription(),p.getStatus(),p.getProgress(),p.getDeadline(),p.getCreatedAt(),p.getUpdatedAt());}}
